"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import { DecisionNode, DiagramFrame, EvidenceNode } from "@diax/ui-react/presentation";
import type { DiaxRelation } from "diax";
import { FileCheck2, GitCommitHorizontal } from "lucide-react";
import type { ReactNode } from "react";

const revision = "3e0f4d8382c500c286fe5d5d29ec28597ed58c7c";
const repository = "https://github.com/tt-a1i/archify";

const sources = [
  {
    id: "bounded-authoring",
    eyebrow: "Authoring contract",
    title: "Write the candidate before reading renderer internals",
    description:
      "The first pass stays semantic, automatic, and bounded; repair follows diagnostics.",
    path: "archify/SKILL.md",
    lines: "L15-L37",
  },
  {
    id: "scenario-registry",
    eyebrow: "Content source",
    title: "Scenario guidance is one immutable data projection",
    description:
      "The same records preserve localized questions, required facts, and presentation policy.",
    path: "archify/recipes/scenarios.mjs",
    lines: "L235-L264",
  },
  {
    id: "verified-evidence",
    eyebrow: "Proof boundary",
    title: "Repository evidence fails closed at the pinned revision",
    description:
      "Commit, blob, and line-range checks happen before stable source links are emitted.",
    path: "archify/renderers/shared/repository-evidence.mjs",
    lines: "L149-L234",
  },
] as const;

const relations: readonly DiaxRelation<ReactNode>[] = sources.map((source) => ({
  id: `${source.id}-decision`,
  from: source.id,
  to: "adoption-decision",
  color: "#6676a8",
  targetMarker: "arrow",
  gap: 8,
  label: <RelationLabel>supports</RelationLabel>,
}));

function sourceHref(path: string, lines: string) {
  return `${repository}/blob/${revision}/${path}#${lines}`;
}

export default function RepositoryEvidenceMap() {
  return (
    <DiagramFrame
      data-showcase-corpus="repository-evidence-map"
      eyebrow="Repository evidence · Authored DOM"
      title="Pin the fact before drawing the conclusion."
      description="Source links remain reviewable because every path and line range names one immutable commit."
      icon={<GitCommitHorizontal aria-hidden="true" />}
      caption="This specimen demonstrates trusted evidence already verified by the authoring workflow. DiaX performs no Git or network access."
      className="w-full max-w-[1120px] [--diax-accent:#91a0d0] [--diax-frame-bg:#0b1018] [--diax-frame-radius:3px] [--diax-frame-shadow:none] [--diax-node-bg:#111824] [--diax-node-border:#334057] [--diax-node-shadow:none] [--diax-node-text:#e7ebf4] [--diax-ui-radius:3px]"
    >
      <div className="mb-5 grid border-y border-slate-700 sm:grid-cols-[minmax(0,1fr)_auto]">
        <div className="min-w-0 px-3 py-3 sm:border-r sm:border-slate-700">
          <p className="m-0 font-mono text-[8px] font-bold uppercase tracking-[0.1em] text-slate-500">
            Repository
          </p>
          <p className="m-0 mt-1 truncate text-[10px] text-slate-300">{repository}</p>
        </div>
        <div className="min-w-0 border-t border-slate-700 px-3 py-3 sm:border-t-0">
          <p className="m-0 font-mono text-[8px] font-bold uppercase tracking-[0.1em] text-slate-500">
            Full revision
          </p>
          <code className="mt-1 block truncate font-mono text-[9px] text-indigo-200">
            {revision}
          </code>
        </div>
      </div>

      <ConnectionSurface
        relations={relations}
        pathType="orthogonal"
        aria-label="Pinned source facts supporting one adoption decision"
        className="grid gap-20 py-2 sm:grid-cols-3 sm:gap-x-4 sm:gap-y-24 sm:py-4"
      >
        {sources.map((source) => (
          <EvidenceNode
            key={source.id}
            {...connectionTarget(source.id)}
            eyebrow={source.eyebrow}
            title={source.title}
            description={source.description}
            strength="high"
            strengthLabel="verified source"
            sourceLabel="Pinned citation"
            source={
              <a
                href={sourceHref(source.path, source.lines)}
                target="_blank"
                rel="noreferrer"
                className="font-mono text-[9px] text-indigo-200 underline decoration-indigo-300/40 underline-offset-2 focus-visible:outline-2 focus-visible:outline-indigo-300"
              >
                {source.path} · {source.lines}
              </a>
            }
            className="relative max-w-none"
          />
        ))}

        <DecisionNode
          {...connectionTarget("adoption-decision")}
          title="Adopt the discipline, preserve the DiaX product boundary"
          outcome="Question-first corpus, bounded repair, and pinned evidence stay in authoring and Docs seams."
          criteria={[
            "No new diagram modes",
            "No Git or network access in Core",
            "No inferred runtime causality",
          ]}
          rationale="The source facts justify an evidence loop; they do not justify copying Archify's renderer or coordinate model."
          status="approved"
          owner="DiaX architecture"
          icon={<FileCheck2 aria-hidden="true" />}
          className="relative max-w-none sm:col-span-3 sm:mx-auto sm:w-[54%]"
        />
      </ConnectionSurface>
    </DiagramFrame>
  );
}

function RelationLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-slate-600 bg-[#0b1018] px-2 py-1 font-mono text-[8px] font-bold uppercase tracking-[0.06em] text-slate-300">
      {children}
    </span>
  );
}
